import module namespace set = "http://qt4cg.org/atomic-set";
let $s := set:of(("a", "b", "c"))
return ($s =?> contains("a"), $s =?> contains("z"))

import module namespace set = "http://qt4cg.org/atomic-set";
let $s := set:of(("a", "b", "c"))
return ($s =?> contains-all(set:of(("a", "c"))), 
        $s =?> contains-all(set:of(("a", "z")))
       )

import module namespace set = "http://qt4cg.org/atomic-set";
let $s := set:of(("a", "b", "c")) =?> remove("b")
return ($s =?> size(), $s =?> contains("a"), $s =?> contains("c"))

import module namespace set = "http://qt4cg.org/atomic-set";
let $s := set:of(("a", "b", "c")) =?> remove("z")
return ($s =?> size(), $s =?> contains("a"), $s =?> contains("c"))

import module namespace set = "http://qt4cg.org/atomic-set";
let $s := set:of(1 to 5) =?> union(set:of(3 to 7))
return ($s =?> size(), $s =?> contains-all(set:of(1 to 7)))

import module namespace set = "http://qt4cg.org/atomic-set";
let $s := set:of(1 to 5) =?> intersect(set:of(3 to 7))
return ($s =?> size(), $s =?> contains-all(set:of(3 to 5)))

import module namespace set = "http://qt4cg.org/atomic-set";
let $s := set:of(1 to 10) =?> except(set:of(3 to 7))
return ($s =?> size(), $s =?> contains-all(set:of((1, 2, 8, 9, 10))))
